#!/bin/bash
perl -0777 -pi -e 's/Spacer\(modifier = Modifier\.weight\(1f\)\)\n\s*IconButton\(\n\s*onClick = \{ showEditProfileDialog = true \},\n\s*modifier = Modifier\.size\(36\.dp\)\.clip\(CircleShape\)\.background\(AppTextColor\(\)\.copy\(alpha = 0\.05f\)\)\n\s*\) \{\n\s*Icon\(Icons\.Default\.Edit, contentDescription = "Edit Profile", tint = AppTextColor\(\), modifier = Modifier\.size\(16\.dp\)\)\n\s*\}\n\s*\}\n\s*IconButton\(\n\s*onClick = \{ showEditProfileDialog = true \},\n\s*modifier = Modifier\n\s*\.size\(36\.dp\)\n\s*\.background\(getGlassIconButtonBg\(\), CircleShape\)\n\s*\.border\(1\.dp, getGlassBorder\(\), CircleShape\)\n\s*\) \{\n\s*Icon\(Icons\.Default\.Edit, contentDescription = "Edit Profile", tint = AccentCyan, modifier = Modifier\.size\(18\.dp\)\)\n\s*\}\n\s*\}/Spacer(modifier = Modifier.weight(1f))\n                        IconButton(\n                            onClick = { showEditProfileDialog = true },\n                            modifier = Modifier.size(36.dp).background(getGlassIconButtonBg(), CircleShape).border(1.dp, getGlassBorder(), CircleShape)\n                        ) {\n                            Icon(Icons.Default.Edit, contentDescription = "Edit Profile", tint = AccentCyan, modifier = Modifier.size(18.dp))\n                        }\n                    }/gs' app/src/main/java/com/example/ui/screens/settings/subscreens/ProfileSettingsScreen.kt
